package com.tcl.backend.messaging;

import com.tcl.backend.transactions.TransactionCache;
import java.util.Map;

// Interface for signing/building the cryptographic identity of an outbound transaction.
// CampaignService/TransactionService do not depend on a concrete signer.
// Current implementation calls the on-chain wallet/signing REST API.
//
// Simple analogy:
// txHash = document fingerprint.
// signature = person's approval/signature on the document.
public interface TransactionSigner {

    // Sign one outbound transaction message.
    // nonceOrder is generated by backend before mempool publish.
    // senderAddress and targetAddress are included so the signer/hash covers the route of funds.
    // timestamp and payload must match the exact JSON that will later be published to RabbitMQ.
    SignedTransaction sign(
            TransactionCache transaction,
            long nonceOrder,
            String senderAddress,
            String targetAddress,
            long timestamp,
            Map<String, Object> payload
    );
}
